begin;
alter table public.ltch_accounts add column if not exists email text check (length(email)<=254);
alter table public.ltch_class_memberships add column if not exists permissions text[] not null default '{}' check (permissions <@ array['attendance.write','materials.write','assignments.write','practice.manage']::text[]);
create table public.ltch_materials(id text primary key,class_id text not null references public.ltch_classes(id),title text not null check(length(title) between 1 and 250),topic text not null default '' check(length(topic)<=200),object_path text not null unique,status text not null check(status in ('pending','stored','failed')),content_type text,file_size integer,created_by text not null references public.ltch_accounts(uid),created_at bigint not null);
create index on public.ltch_materials(class_id);
create table public.ltch_attendance(id text primary key,class_id text not null references public.ltch_classes(id),student_uid text not null references public.ltch_accounts(uid),lesson_date date not null,status text not null check(status in ('present','absent','late','excused')),note text not null default '' check(length(note)<=1000),recorded_by text not null references public.ltch_accounts(uid),updated_at bigint not null,unique(class_id,student_uid,lesson_date));
create index on public.ltch_attendance(student_uid,class_id);
create table public.ltch_notices(id text primary key,class_id text not null references public.ltch_classes(id),title text not null check(length(title) between 1 and 250),body text not null check(length(body) between 1 and 20000),created_by text not null references public.ltch_accounts(uid),created_at bigint not null);
create index on public.ltch_notices(class_id);
create table public.ltch_messages(id text primary key,class_id text not null references public.ltch_classes(id),sender_uid text not null references public.ltch_accounts(uid),recipient_uid text not null references public.ltch_accounts(uid),body text not null check(length(body) between 1 and 10000),created_at bigint not null,check(sender_uid<>recipient_uid));
create index on public.ltch_messages(recipient_uid,class_id);
create index on public.ltch_messages(sender_uid,class_id);
alter table public.ltch_submissions add column if not exists feedback text not null default '' check(length(feedback)<=10000);
alter table public.ltch_materials enable row level security;
alter table public.ltch_attendance enable row level security;
alter table public.ltch_notices enable row level security;
alter table public.ltch_messages enable row level security;
revoke all on public.ltch_materials,public.ltch_attendance,public.ltch_notices,public.ltch_messages from public,anon,authenticated;
grant select,insert,update,delete on public.ltch_materials,public.ltch_attendance,public.ltch_notices,public.ltch_messages to service_role;
commit;
